using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tool class that wraps the Open-Meteo REST API.
/// Constructor parameters are resolved from the DI container automatically.
/// </summary>
public class WeatherTools(IHttpClientFactory httpClientFactory)
{
    [McpServerTool(Name = "get_weather"),
     Description("Gets current weather for a given latitude and longitude.")]
    public async Task<string> GetWeatherAsync(
        [Description("Latitude (e.g. 47.6)")] double latitude,
        [Description("Longitude (e.g. -122.3)")] double longitude)
    {
        var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current_weather=true";

        var response = await client.GetFromJsonAsync<JsonElement>(url);

        if (response.TryGetProperty("current_weather", out var weather))
        {
            return $"Temperature: {weather.GetProperty("temperature")}°C, "
                 + $"Wind: {weather.GetProperty("windspeed")} km/h, "
                 + $"Direction: {weather.GetProperty("winddirection")}°";
        }

        return "Unable to retrieve weather data.";
    }

    [McpServerTool(Name = "get_forecast_summary"),
     Description("Gets a multi-day temperature forecast summary.")]
    public async Task<string> GetForecastSummaryAsync(
        [Description("Latitude")] double latitude,
        [Description("Longitude")] double longitude,
        [Description("Number of forecast days (1-7)")] int days = 3)
    {
        var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + $"&daily=temperature_2m_max,temperature_2m_min&forecast_days={days}";

        var response = await client.GetFromJsonAsync<JsonElement>(url);

        if (response.TryGetProperty("daily", out var daily))
        {
            return daily.ToString();
        }

        return "Unable to retrieve forecast data.";
    }
}

